	 ('6bd38a1d-de18-469d-89c7-9b19fcf98fbe'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'So if a drone, and you know, these drones cost $50,000 if they wiped out a desalination','en',916,17,185,192,31,'2026-03-21 13:29:02.059471+07','2026-03-21 13:29:02.059471+07'),
	 ('449c475c-33bf-417e-8a45-831a0e930ecf'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'plant in Riyadh, Saudi Arabia, and it''s a city of 10 million people.','en',916,13,192,196,32,'2026-03-21 13:29:02.063925+07','2026-03-21 13:29:02.063925+07');
INSERT INTO course_management.video_transcripts (id,video_lecture_id,transcript_text,language_code,audio_duration,word_count,start_time_seconds,end_time_seconds,segment_index,created_at,updated_at) VALUES
	 ('315e5023-d07a-47e3-a28a-297574274cd3'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'Right. They''d be out of water in two weeks.','en',916,9,196,200,33,'2026-03-21 13:29:02.067837+07','2026-03-21 13:29:02.067837+07'),
