	 ('741e587c-11d3-496f-a487-81f2fb501a74'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'And the GCC gets 90% of its food from the','en',916,10,207,214,35,'2026-03-21 13:29:02.072471+07','2026-03-21 13:29:02.072471+07'),
	 ('0af472b8-06b4-4317-b4d4-658b874941d2'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'strip of Hormuz. So I know a lot of you are talking about the disruptions to global economy, but right','en',916,20,214,220,36,'2026-03-21 13:29:02.076863+07','2026-03-21 13:29:02.076863+07'),
	 ('ca803978-1f41-4dfd-bcd0-244baeee2175'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'now the Iranians are actually threatening the very existence of Saudi Arabia, uae,','en',916,13,220,227,37,'2026-03-21 13:29:02.081072+07','2026-03-21 13:29:02.081072+07'),
	 ('315d445b-1249-4cf1-a47e-582da8a69839'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'Bahrain, Qatar. And why this is important is that the','en',916,10,227,233,38,'2026-03-21 13:29:02.0851+07','2026-03-21 13:29:02.0851+07'),
	 ('98bb8a39-6651-4b4b-b9da-a9c79f19f76b'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'So what they do is they sell petrodollars and then they recycle the petrodollars back into the American economy','en',916,19,238,244,40,'2026-03-21 13:29:02.093911+07','2026-03-21 13:29:02.093911+07'),
