	 ('8777cba8-36a5-4fa8-b11c-e1222f28d2b0'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'propped up by investments in data centers. And a lot of that comes from the Gulf states.','en',916,17,251,257,42,'2026-03-21 13:29:02.100157+07','2026-03-21 13:29:02.100157+07'),
