	 ('77d8d07c-47af-4851-a552-9a5fd6570770'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'And now of course, big tech companies, which were looking at the UAE as a major potential data center investment hub with cheap','en',916,23,287,293,48,'2026-03-21 13:29:02.117315+07','2026-03-21 13:29:02.117315+07'),
