	 ('b639d820-6fff-4b8a-a935-e80f5eb3d3d9'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'We also wanted to talk to you about munitions. We can put this next one up here on the screen.','en',916,20,297,301,50,'2026-03-21 13:29:02.124784+07','2026-03-21 13:29:02.124784+07'),
