	 ('653aa555-9abe-47ad-b65f-9dd48fa9b82e'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'This is specifically around interceptor math. There''s a famous video just from yesterday in Israel which shows','en',916,17,306,312,52,'2026-03-21 13:29:02.130585+07','2026-03-21 13:29:02.130585+07'),
