	 ('3b9123e5-de92-46b5-bda4-a5bcb63dddf5'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'which, miss, most of those come from the United States, not to mention all of the different bases, the GCC countries that','en',916,22,318,324,54,'2026-03-21 13:29:02.136115+07','2026-03-21 13:29:02.136115+07'),
