	 ('ab7a7e55-a5a4-4632-9b59-219e1f4eca1a'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'With these munitions running out, how does that change the global picture?','en',916,12,332,336,57,'2026-03-21 13:29:02.146488+07','2026-03-21 13:29:02.146488+07'),
