	 ('bf87a7c8-4a51-491f-a9e6-0c2bbd0a29ae'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'if this were to go on. How''s that going to affect the global picture here?','en',916,15,342,345,59,'2026-03-21 13:29:02.150762+07','2026-03-21 13:29:02.150762+07'),
	 ('b1c22e07-300b-4999-bca4-8d449d58be75'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'Right. So my first point is that the United States military is not designed to fight','en',916,16,346,352,60,'2026-03-21 13:29:02.152994+07','2026-03-21 13:29:02.152994+07'),
	 ('b3371a6e-e2e1-402d-8a56-85f92fda0d88'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'against a 21st century war. Remember the military industrial complex came to being after World War II and it''s designed','en',916,20,352,358,61,'2026-03-21 13:29:02.155273+07','2026-03-21 13:29:02.155273+07'),
	 ('67385b35-87cb-4121-ab2b-bdfedab814f4'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'to fight the Cold War. And the Cold War was really about muscle flexing about about who was able to send people up into space,','en',916,25,358,365,62,'2026-03-21 13:29:02.157156+07','2026-03-21 13:29:02.157156+07'),
	 ('0e16e5cd-9acf-479e-8c76-71c71fd19877'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'was able to, who was the first get the person on the moon who had the more complex missile','en',916,19,365,372,63,'2026-03-21 13:29:02.159868+07','2026-03-21 13:29:02.159868+07');
INSERT INTO course_management.video_transcripts (id,video_lecture_id,transcript_text,language_code,audio_duration,word_count,start_time_seconds,end_time_seconds,segment_index,created_at,updated_at) VALUES
	 ('626974d7-f8cb-4bdb-a6e1-e8d00c790de0'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'systems. And so the entire American military strategy revolves around very sophisticated','en',916,12,372,379,64,'2026-03-21 13:29:02.161907+07','2026-03-21 13:29:02.161907+07'),
	 ('b05b9e15-947c-4373-b6b1-ff799a8a2e39'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'technology that, that costs a lot of money to build.','en',916,10,379,383,65,'2026-03-21 13:29:02.165473+07','2026-03-21 13:29:02.165473+07'),
	 ('fb5f3f2d-5957-4ecb-83d6-0747da93483d'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'And that''s what the American air defense system is basically.','en',916,10,383,388,66,'2026-03-21 13:29:02.166701+07','2026-03-21 13:29:02.166701+07'),
	 ('9cc53d24-0d4d-43cc-960c-26aa0c91e273'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'And that''s why we''re seeing this asymmetry as you point out, in this war where you have these million dollar missiles','en',916,21,388,395,67,'2026-03-21 13:29:02.168553+07','2026-03-21 13:29:02.168553+07'),
	 ('2fa57249-525c-42e9-b40b-ae93fe946cf5'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'trying to take out these $50,000 drones. And it''s not sustainable in the long term.','en',916,15,395,399,68,'2026-03-21 13:29:02.170437+07','2026-03-21 13:29:02.170437+07'),
	 ('0e48bf2e-6fe8-41e7-ac72-6c690f5ac132'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'And so what we''re seeing is really the puncturing of the aura of invincibility','en',916,14,400,406,69,'2026-03-21 13:29:02.172749+07','2026-03-21 13:29:02.172749+07'),
	 ('e8b29737-8908-4e22-a3ee-563380c6b537'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'and invisibility that sustain American hegemony for the past 20 years, especially after the collapse','en',916,15,406,412,70,'2026-03-21 13:29:02.174852+07','2026-03-21 13:29:02.174852+07'),
	 ('b794143b-8ca2-43a0-b57b-b5e5c99b0d63'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'of the Soviet Union. And this is really a reordering of not just a global economy because','en',916,17,412,418,71,'2026-03-21 13:29:02.177475+07','2026-03-21 13:29:02.177475+07'),
	 ('bd21f4e6-02d0-41ad-943b-94a501d040c1'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'this signals the collapse of the petrodollar and with it the entire US dollar based','en',916,15,419,425,72,'2026-03-21 13:29:02.179939+07','2026-03-21 13:29:02.179939+07'),
	 ('4b17ffae-c76d-42fe-a8ff-3cec3ae6c725'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'reserve currency system, but also global, the global hegemony of the United States.','en',916,13,425,431,73,'2026-03-21 13:29:02.181948+07','2026-03-21 13:29:02.181948+07');
INSERT INTO course_management.video_transcripts (id,video_lecture_id,transcript_text,language_code,audio_duration,word_count,start_time_seconds,end_time_seconds,segment_index,created_at,updated_at) VALUES
	 ('15cc2d21-4223-4425-b399-55e6be19865f'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'We''re moving towards a multipolar world. Professor this morning, Secretary of War Pete Hegseth','en',916,14,431,437,74,'2026-03-21 13:29:02.183638+07','2026-03-21 13:29:02.183638+07'),
	 ('56ade884-62f9-4295-aa8e-13bd742e7d07'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'was asked a question about potential ground troops in Iran.','en',916,10,437,442,75,'2026-03-21 13:29:02.187247+07','2026-03-21 13:29:02.187247+07'),
	 ('1bc0d80e-df22-4f79-930f-0c53c3ddcbaf'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'He refused to rule out that possibility. And he said, you know, oh well, we''re not going to project to you what','en',916,22,442,448,76,'2026-03-21 13:29:02.18925+07','2026-03-21 13:29:02.18925+07'),
	 ('0bf528ce-5320-4778-8413-14ea4ba6eb7c'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'we will or will not do, what we don''t want to rule anything out.','en',916,14,448,452,77,'2026-03-21 13:29:02.191749+07','2026-03-21 13:29:02.191749+07'),
	 ('d0b2501d-95b2-45eb-a5ba-a286ca1e85b7'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'We will do what it takes. Do you think that America will end up invading Iran from the','en',916,18,452,458,78,'2026-03-21 13:29:02.193825+07','2026-03-21 13:29:02.193825+07'),
	 ('94f17d63-7bd4-40da-9e33-67dd16ed5e24'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'ground since it''s already becoming relatively clear they won''t be able to accomplish the goal of regime change or even regime collapse','en',916,22,458,464,79,'2026-03-21 13:29:02.197128+07','2026-03-21 13:29:02.197128+07'),
	 ('373a1b31-d5aa-42db-9a8d-e64364363379'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'using just air power alone. Right? So everyone says that the worst calamity that could happen in','en',916,17,464,470,80,'2026-03-21 13:29:02.20022+07','2026-03-21 13:29:02.20022+07'),
	 ('62ca7da6-2bf7-4921-af46-6b447fc647a6'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'the United States is if it were to send ground troops into Iran.','en',916,13,470,474,81,'2026-03-21 13:29:02.202614+07','2026-03-21 13:29:02.202614+07'),
	 ('e44f242a-7044-42ed-be3e-54045898acf6'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'At the same time the United States are committed to regime change in Iran.','en',916,14,474,479,82,'2026-03-21 13:29:02.203992+07','2026-03-21 13:29:02.203992+07'),
	 ('394d88f4-2cf7-4c20-a04d-8e48799fd478'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'We''ve never had a precedent in history where you were able to regime change from the air alone.','en',916,18,479,485,83,'2026-03-21 13:29:02.205756+07','2026-03-21 13:29:02.205756+07');
INSERT INTO course_management.video_transcripts (id,video_lecture_id,transcript_text,language_code,audio_duration,word_count,start_time_seconds,end_time_seconds,segment_index,created_at,updated_at) VALUES
	 ('418492d8-4a4a-43e6-b17e-5720a925f9ee'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'You need ground troops. And so unfortunately what''s going to happen over the next few months is that','en',916,18,485,491,84,'2026-03-21 13:29:02.206914+07','2026-03-21 13:29:02.206914+07'),
	 ('c69fdb82-0c78-421a-ba43-5fb8f5a66145'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'pressure will build on America to send ground troops, especially from the GCC countries and from Israel,','en',916,17,492,498,85,'2026-03-21 13:29:02.209867+07','2026-03-21 13:29:02.209867+07'),
	 ('ee67b454-0fd4-48a7-ad4d-b09ae3ad6c76'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'which are being pounded right now by the Iranians.','en',916,9,498,502,86,'2026-03-21 13:29:02.21098+07','2026-03-21 13:29:02.21098+07'),
