	 ('10cd77ff-d0bb-4ccb-9ab8-42d007ac7832'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'Okay? So hubris is a factor. And we see this throughout history.','en',916,12,740,743,130,'2026-03-21 13:29:02.296927+07','2026-03-21 13:29:02.296927+07'),
	 ('f53200c1-7f8a-4faf-94ba-6fe80efb084e'::uuid,'74e22a79-6b77-413f-9053-f6f79566226b'::uuid,'Why did Hitler invade Stalin? Because he conquered Europe really easily and he thought he was invincible.','en',916,17,743,748,131,'2026-03-21 13:29:02.299063+07','2026-03-21 13:29:02.299063+07'),
